alter table public.profiles add column if not exists birth_date date, add column if not exists age_band text check(age_band in ('under_13','teen','adult'));
create table public.age_safety_settings(user_id uuid primary key references public.profiles(id) on delete cascade,direct_messages text not null default 'age_appropriate' check(direct_messages in ('off','friends','age_appropriate')),location_sharing_allowed boolean not null default false,marketplace_allowed boolean not null default false,payments_allowed boolean not null default false,live_hosting_allowed boolean not null default false,personalized_promotions_allowed boolean not null default false,updated_at timestamptz not null default now());
create table public.guardian_links(id uuid primary key default gen_random_uuid(),minor_user_id uuid not null references public.profiles(id) on delete cascade,guardian_user_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in ('pending','active','revoked')),created_at timestamptz not null default now(),unique(minor_user_id,guardian_user_id));
alter table public.age_safety_settings enable row level security;alter table public.guardian_links enable row level security;
create policy "users read own age safety" on public.age_safety_settings for select to authenticated using(user_id=auth.uid());create policy "users manage own age safety" on public.age_safety_settings for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "guardian links visible to participants" on public.guardian_links for select to authenticated using(minor_user_id=auth.uid() or guardian_user_id=auth.uid());
create policy "guardian link participants create" on public.guardian_links for insert to authenticated with check(minor_user_id=auth.uid() or guardian_user_id=auth.uid());
create or replace function public.set_age_band() returns trigger language plpgsql set search_path=public as $$ begin if new.birth_date is null then new.age_band=null; elsif new.birth_date > current_date-interval '13 years' then new.age_band='under_13'; elsif new.birth_date > current_date-interval '18 years' then new.age_band='teen'; else new.age_band='adult'; end if; return new; end; $$;
drop trigger if exists profiles_age_band on public.profiles;create trigger profiles_age_band before insert or update of birth_date on public.profiles for each row execute function public.set_age_band();
create trigger age_safety_settings_set_updated_at before update on public.age_safety_settings for each row execute function public.set_updated_at();
